def tearDown(self) -> None:
        if self.old_provider is None:
            os.environ.pop("CKB_TEST_PROVIDER", None)
        else:
            os.environ["CKB_TEST_PROVIDER"] = self.old_provider
        try:
            self.temporary.cleanup()
        except OSError:
            # Windows may release a recently relocated SQLite/plugin directory
            # one scheduling turn after the rollback verification closes it.
            time.sleep(0.2)
            shutil.rmtree(self.root, ignore_errors=True)

def _manifest(self, projects: list[dict[str, object]] | None = None) -> Path:
        from ckb_core.common import json_write

        manifest = self.root / "manifest.json"
        json_write(
            manifest,
            {
                "schema_version": 1,
                "batch_id": "fixture-batch",
                "allowed_roots": [str(self.root.resolve()), str(ROOT.resolve())],
                "projects": projects or [self._project_document("project-a", self.output, self.repo, self.staging)],
            },
        )
        return manifest

def plan_for(project: dict[str, object], suffix: str) -> dict[str, object]:
            manifest = self.root / f"manifest-{suffix}.json"
            json_write(
                manifest,
                {
                    "schema_version": 1,
                    "batch_id": f"batch-{suffix}",
                    "allowed_roots": [str(self.root.resolve()), str(ROOT.resolve())],
                    "projects": [project],
                },
            )
            return create_knowledge_batch_plan(manifest)

def guarded(output: Path, relative: str) -> dict[str, object]:
            observed.append(relative)
            self.assertIn(relative, REQUIRED_RECORDS)
            return original(output, relative)

def git(repo: Path, *args: str) -> str:
    completed = subprocess.run(
        ["git", "-C", str(repo), *args],
        text=True,
        stdout=subprocess.PIPE,
        stderr=subprocess.PIPE,
    )
    if completed.returncode:
        raise RuntimeError(completed.stderr)
    return completed.stdout.strip()

def review_all(output: Path) -> None:
    state = json.loads((output / "state.json").read_text(encoding="utf-8"))
    for batch in state["parse_batches"]:
        if not (output / "chunks" / batch["id"] / "candidate.json").is_file():
            build_chunk(output, batch["id"], "all")
    state = json.loads((output / "state.json").read_text(encoding="utf-8"))
    for pack in state["review_packs"]:
        if pack["status"] == "passed":
            continue
        template = json.loads(Path(pack["review_template_path"]).read_text(encoding="utf-8"))
        for item in template["reviews"]:
            item["status"] = "agent-reviewed"
            item["evidence_note"] = "Agent 已重新打开固定 Git 源码范围，核对名称、签名、分支和调用关系后确认本条说明。"
            if pack["kind"] == "appendix-review":
                item["description_zh"] = "该局部代码负责完成所属流程中的辅助处理，并把结果交给主流程继续使用。"
            else:
                item["meaning_zh"] = "该代码页说明固定源码范围内的主要实现及其输入输出约定。"
                item["role_zh"] = "它负责组织当前代码单元的处理步骤，并与相邻函数形成可追踪的调用关系。"
                item["change_when_zh"] = "当输入约定、处理步骤、返回结果或调用关系变化时，需要修改该代码单元并同步验证。"
        review_path = output / "test-reviews" / f"{pack['id']}.json"
        review_path.parent.mkdir(parents=True, exist_ok=True)
        review_path.write_text(json.dumps(template, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
        review_pack(output, pack["id"], review_path)

def tearDown(self) -> None:
        if self.old_provider is None:
            os.environ.pop("CKB_TEST_PROVIDER", None)
        else:
            os.environ["CKB_TEST_PROVIDER"] = self.old_provider
        self.temporary.cleanup()

def test_core_packages_exclude_plugins_and_full_only_adds_runtime(self) -> None:
        lite = {path.relative_to(ROOT).as_posix() for path in PACKAGE_RELEASE.source_files(False)}
        full = {path.relative_to(ROOT).as_posix() for path in PACKAGE_RELEASE.source_files(True)}
        self.assertTrue(set(PACKAGE_RELEASE.CORE_REQUIRED_FILES) <= lite)
        self.assertFalse(any(path == "plugins" or path.startswith("plugins/") for path in lite | full))
        self.assertLess(lite, full)
        self.assertTrue(all(path.startswith("assets/runtime/win-x64/") for path in full - lite))
